{"ok": true, "result": {"path": "views/play.js", "text": "import { useEffect, useRef } from 'preact/hooks';
import { html, SaveIndicator, ConflictBanner } from 'spaces-kit';
import { CARD_BACKS, fruitName } from '../game.js';

function Settings({settings}) {
  const {values, change, save} = settings;
  return html`
    <section class="pp-panel" aria-labelledby="pp-settings-h">
      <h2 id="pp-settings-h">Settings</h2>
      <div role="group" aria-label="Game settings" class="pp-settings">
        <label>Card back
          <select value=${values.cardBack} disabled=${save.state === 'saving'}
            onChange=${e => change({cardBack: e.target.value})}>
            ${CARD_BACKS.map(b => html`<option key=${b.id} value=${b.id} selected=${values.cardBack === b.id}>${b.symbol} ${b.label}</option>`)}
          </select>
        </label>
        <label class="pp-check">
          <input type="checkbox" checked=${!!values.showNames} disabled=${save.state === 'saving'}
            onChange=${e => change({showNames: e.target.checked})} />
          Show fruit names on cards
        </label>
      </div>
      <${SaveIndicator} state=${save.state} message=${save.message} />
    </section>`;
}

export function Play({game: g, settings}) {
  const {game, pending, save, actions, loading, error, corrupt} = g;
  const back = CARD_BACKS.find(b => b.id === settings.values.cardBack) || CARD_BACKS[0];
  const showNames = !!settings.values.showNames;
  const continueBtn = useRef(null);
  const newBtn = useRef(null);
  const cards = useRef([]);
  const lastMismatch = useRef([]);
  const status = game?.status;

  useEffect(() => {
    if (status === 'mismatch') {
      lastMismatch.current = game.revealed.slice();
      continueBtn.current?.focus();
    } else if (status === 'won') {
      newBtn.current?.focus();
    }
  }, [status]);

  const proceed = () => {
    const first = game.revealed[0];
    actions.proceed();
    if (first != null) setTimeout(() => cards.current[first]?.focus(), 0);
  };

  if (error && !game) return html`<p role="alert">Could not load the game. ${error.message}</p>`;
  if (!game) return html`<p role="status">${corrupt ? 'Saved round could not be read.' : 'Setting up the board...'}</p>${corrupt && html`<button type="button" class="pp-btn" onClick=${actions.newRound}>Start a fresh round</button>`}`;

  const pairsFound = game.matched.length / 2;
  const faceUp = i => game.matched.includes(i) || game.revealed.includes(i);
  const message = status === 'won'
    ? `You found all 6 pairs in ${game.turns} ${game.turns === 1 ? 'turn' : 'turns'}!`
    : status === 'mismatch'
      ? 'Not a match. Press Continue to turn both cards back over.'
      : game.revealed.length === 1
        ? 'Pick a second card.'
        : 'Pick a card to start your turn.';
  const locked = !!pending || save.state === 'saving';

  return html`
    <section aria-labelledby="pp-board-h">
      <h2 id="pp-board-h" class="pp-sr">Board</h2>
      <div class="pp-stats">
        <div><span class="pp-stat-n">${game.turns}</span><span class="pp-stat-l">${game.turns === 1 ? 'Turn' : 'Turns'}</span></div>
        <div><span class="pp-stat-n">${pairsFound}/6</span><span class="pp-stat-l">Pairs found</span></div>
        <button type="button" class="pp-btn pp-btn-secondary" ref=${status === 'won' ? null : newBtn}
          disabled=${locked} onClick=${actions.newRound}>New round</button>
      </div>

      <p class="pp-message ${status === 'won' ? 'pp-won' : ''}" role="status" aria-live="polite">${message}</p>

      <div class="pp-board" role="group" aria-label="Cards, 4 columns by 3 rows">
        ${game.deck.map((emoji, i) => {
          const up = faceUp(i);
          const matched = game.matched.includes(i);
          const mismatched = status === 'mismatch' && game.revealed.includes(i);
          const name = fruitName(emoji);
          const label = `Card ${i + 1}, ${up ? name + (matched ? ', matched' : mismatched ? ', not a match' : '') : 'face down'}`;
          return html`<button key=${i} type="button" ref=${el => { cards.current[i] = el; }}
            class="pp-card ${up ? 'up' : ''} ${matched ? 'matched' : ''} ${mismatched ? 'miss' : ''}"
            aria-label=${label} aria-disabled=${matched || status !== 'playing' || locked ? 'true' : 'false'}
            onClick=${() => actions.flip(i)}>
            <span class="pp-face" aria-hidden="true">${up ? emoji : back.symbol}</span>
            ${up && showNames && html`<span class="pp-name" aria-hidden="true">${name}</span>`}
            ${matched && html`<span class="pp-tick" aria-hidden="true">✓</span>`}
          </button>`;
        })}
      </div>

      ${status === 'mismatch' && html`
        <button type="button" class="pp-btn pp-continue" ref=${continueBtn} disabled=${locked} onClick=${proceed}>Continue</button>`}
      ${status === 'won' && html`
        <div class="pp-win">
          <p><strong>Round complete.</strong> Saved to History.</p>
          <button type="button" class="pp-btn" ref=${newBtn} disabled=${locked} onClick=${actions.newRound}>Play again</button>
        </div>`}

      <${SaveIndicator} state=${save.state} message=${save.message} />
      ${pending && save.state === 'failed' && html`
        <div class="pp-recover" role="group" aria-label="Unsaved move">
          <p role="alert">Your last move is not saved yet.</p>
          <button type="button" class="pp-btn" onClick=${actions.retry}>Retry save</button>
          <button type="button" class="pp-btn pp-btn-secondary" onClick=${() => actions.useSaved()}>Discard move</button>
        </div>`}
      ${pending && save.state === 'conflict' && html`
        <${ConflictBanner} current=${save.current}
          onKeepMine=${actions.keepMine} onUseUpdated=${actions.useSaved}
          message="This round was changed somewhere else. Keep mine saves your move over it; Use updated loads the saved round." />`}
    </section>
    <${Settings} settings=${settings} />`;
}
