{"ok": true, "result": {"path": "store.js", "text": "import { useEffect, useRef, useState } from 'preact/hooks';
import { useCollection, useSaveState } from 'spaces-kit';
import { newGame, validGame, flipCard, continueAfterMismatch } from './game.js';

const space = window.space;

// Owns the current round. The saved record is the source of truth; the local
// copy is shown immediately and rolled forward only after a confirmed write.
export function useGame() {
  const col = useCollection('game', {limit: 5});
  const save = useSaveState();
  const record = col.records.find(r => r.id === 'current');
  const [game, setGame] = useState(null);
  const [pending, setPending] = useState(null); // {next, ops} not yet saved
  const rev = useRef(0);
  const saved = useRef(null);
  const busy = useRef(false);
  const creating = useRef(false);

  // Adopt the saved record (first load, or a change made elsewhere).
  useEffect(() => {
    if (!record || busy.current || pending) return;
    if (record.rev !== rev.current && validGame(record.data)) {
      rev.current = record.rev;
      saved.current = record.data;
      setGame(record.data);
    }
  }, [record?.rev, pending]);

  // First ever visit: create the first round.
  useEffect(() => {
    if (col.loading || col.error || record || creating.current) return;
    creating.current = true;
    (async () => {
      const first = newGame();
      const created = await save.run(() => space.put('game', 'current', first, {baseRev: 0}));
      if (created) {
        rev.current = created.rev;
        saved.current = first;
        setGame(first);
        col.reload();
      } else creating.current = false;
    })();
  }, [col.loading, col.error, !!record]);

  // A saved record with an unreadable shape is replaced only by explicit action.
  const corrupt = !!record && !validGame(record.data);

  const commit = async (next, ops = []) => {
    if (busy.current) return false;
    busy.current = true;
    setGame(next);
    setPending({next, ops});
    try {
      const result = await save.run(async () => {
        if (ops.length) {
          await space.batch([
            {op: 'put', collection: 'game', id: 'current', data: next, base_rev: rev.current},
            ...ops
          ]);
          return await space.get('game', 'current');
        }
        return await space.put('game', 'current', next, {baseRev: rev.current});
      });
      if (result) {
        rev.current = result.rev;
        saved.current = next;
        setPending(null);
        col.reload();
        return true;
      }
      return false;
    } finally { busy.current = false; }
  };

  const roundOps = next => [{
    op: 'put', collection: 'rounds', id: next.roundId,
    data: {roundId: next.roundId, turns: next.turns, pairs: 6, startedAt: next.startedAt, finishedAt: next.finishedAt},
    base_rev: 0
  }];

  const busyNow = () => busy.current || !!pending || save.state === 'saving' || !game;

  const actions = {
    flip(i) {
      if (busyNow()) return;
      const next = flipCard(game, i);
      if (next === game) return;
      commit(next, next.status === 'won' ? roundOps(next) : []);
    },
    proceed() {
      if (busyNow()) return;
      const next = continueAfterMismatch(game);
      if (next !== game) commit(next);
    },
    newRound() {
      if (busy.current || pending || save.state === 'saving') return;
      commit(newGame());
    },
    retry() { if (pending) { const p = pending; setPending(null); commit(p.next, p.ops); } },
    keepMine(current) {
      if (!pending) return;
      rev.current = current.rev;
      const p = pending; setPending(null); commit(p.next, p.ops);
    },
    useSaved(current) {
      const data = current?.data && validGame(current.data) ? current.data : saved.current;
      if (current?.rev) rev.current = current.rev;
      saved.current = data;
      setPending(null);
      if (data) setGame(data);
      col.reload();
    }
  };

  return {game, pending, save, loading: col.loading, error: col.error, corrupt, actions};
}

export function useSettings() {
  const col = useCollection('settings', {limit: 5});
  const save = useSaveState();
  const record = col.records.find(r => r.id === 'prefs');
  const busy = useRef(false);
  const change = async patch => {
    if (busy.current) return;
    busy.current = true;
    try {
      const base = record?.data || {};
      await save.run(() => space.put('settings', 'prefs', {...base, ...patch}, {baseRev: record?.rev ?? 0}));
      await col.reload();
    } finally { busy.current = false; }
  };
  return {values: {cardBack: 'question', showNames: false, ...(record?.data || {})}, change, save, loading: col.loading};
}
