{"ok": true, "result": {"path": "game.js", "text": "export const FRUITS = [
  {emoji: '🍎', name: 'Apple'},
  {emoji: '🍌', name: 'Banana'},
  {emoji: '🍇', name: 'Grapes'},
  {emoji: '🍓', name: 'Strawberry'},
  {emoji: '🍊', name: 'Orange'},
  {emoji: '🍉', name: 'Watermelon'}
];

export const CARD_BACKS = [
  {id: 'question', label: 'Question mark', symbol: '?'},
  {id: 'star', label: 'Star', symbol: '★'},
  {id: 'diamond', label: 'Diamond', symbol: '◆'}
];

export const DEFAULT_SETTINGS = {cardBack: 'question', showNames: false};

export function shuffle(items) {
  const a = items.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

export function newGame() {
  const now = Date.now();
  return {
    version: 1,
    roundId: `round-${now}-${Math.random().toString(36).slice(2, 8)}`,
    deck: shuffle(FRUITS.flatMap(f => [f.emoji, f.emoji])),
    revealed: [],
    matched: [],
    turns: 0,
    status: 'playing',
    startedAt: now
  };
}

export function fruitName(emoji) {
  return FRUITS.find(f => f.emoji === emoji)?.name || 'fruit';
}

export function validGame(data) {
  return !!data && Array.isArray(data.deck) && data.deck.length === 12 &&
    Array.isArray(data.revealed) && Array.isArray(data.matched) && typeof data.turns === 'number';
}

// Pure move functions: return the next game state.
export function flipCard(game, i) {
  if (game.status !== 'playing' || game.matched.includes(i) || game.revealed.includes(i) || game.revealed.length >= 2) return game;
  const revealed = [...game.revealed, i];
  if (revealed.length < 2) return {...game, revealed};
  const [a, b] = revealed;
  const turns = game.turns + 1;
  if (game.deck[a] === game.deck[b]) {
    const matched = [...game.matched, a, b];
    if (matched.length === game.deck.length) {
      return {...game, revealed: [], matched, turns, status: 'won', finishedAt: Date.now()};
    }
    return {...game, revealed: [], matched, turns};
  }
  return {...game, revealed, turns, status: 'mismatch'};
}

export function continueAfterMismatch(game) {
  if (game.status !== 'mismatch') return game;
  return {...game, revealed: [], status: 'playing'};
}
