import { html, hashRouter, useRoute, Nav } from 'spaces-kit';
import { useGame, useSettings } from './store.js';
import { Play } from './views/play.js';
import { Progress } from './views/progress.js';
import { History } from './views/history.js';

hashRouter({'/': Play, '/play': Play, '/progress': Progress, '/history': History, '*': Play});
const items = [
  {path: '/play', label: 'Play'},
  {path: '/progress', label: 'Progress'},
  {path: '/history', label: 'History'}
];

function App() {
  const route = useRoute();
  const View = route.component;
  const game = useGame();
  const settings = useSettings();
  return html`
    <main class="pp">
      <header class="pp-header">
        <p class="pp-eyebrow">Memory match</p>
        <h1>Pair Play</h1>
      </header>
      <${Nav} items=${items} label="Pair Play views" />
      <${View} game=${game} settings=${settings} />
    </main>`;
}

render(html`<${App} />`, document.getElementById('app'));
