{"ok": true, "result": {"path": "views/history.js", "text": "import { html, useCollection, EmptyState } from 'spaces-kit';

function when(ms) {
  if (!ms) return 'Unknown date';
  return new Date(ms).toLocaleString([], {month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit'});
}

function duration(r) {
  if (!r.startedAt || !r.finishedAt || r.finishedAt < r.startedAt) return '';
  const s = Math.round((r.finishedAt - r.startedAt) / 1000);
  return s >= 60 ? `${Math.floor(s / 60)}m ${s % 60}s` : `${s}s`;
}

export function History() {
  const col = useCollection('rounds', {limit: 500});
  const rounds = col.records
    .map(r => ({id: r.id, ...r.data}))
    .sort((a, b) => (b.finishedAt || 0) - (a.finishedAt || 0));
  const best = rounds.length ? Math.min(...rounds.map(r => r.turns)) : null;
  const avg = rounds.length ? (rounds.reduce((n, r) => n + r.turns, 0) / rounds.length).toFixed(1) : null;
  return html`
    <section aria-labelledby="pp-hist-h">
      <h2 id="pp-hist-h">History</h2>
      ${col.loading && html`<p role="status">Loading rounds...</p>`}
      ${col.error && html`<p role="alert">Could not load history. ${col.error.message}</p>`}
      ${rounds.length ? html`
        <div class="pp-stats">
          <div><span class="pp-stat-n">${rounds.length}</span><span class="pp-stat-l">Rounds</span></div>
          <div><span class="pp-stat-n">${best}</span><span class="pp-stat-l">Best (turns)</span></div>
          <div><span class="pp-stat-n">${avg}</span><span class="pp-stat-l">Average</span></div>
        </div>
        <ol class="pp-list">
          ${rounds.map((r, n) => html`<li key=${r.id} class="pp-row">
            <span class="pp-row-turns">${r.turns}<small> turns</small></span>
            <span class="pp-row-meta">${when(r.finishedAt)}${duration(r) && ` · ${duration(r)}`}${r.turns === best ? ' · Best' : ''}</span>
          </li>`)}
        </ol>` : !col.loading && html`
        <${EmptyState} title="No finished rounds yet"><p>Match all six pairs on the Play view and your result will show up here.</p><//>`}
      <p class="pp-note">Only completed rounds are recorded. Starting a new round mid-game does not add an entry.</p>
    </section>`;
}
