{"ok": true, "result": {"path": "views/progress.js", "text": "import { html, useCollection } from 'spaces-kit';
import { FRUITS } from '../game.js';

const MIN_TURNS = 6; // a perfect memory finds six pairs in six turns

function plural(n, word) { return `${n} ${word}${n === 1 ? '' : 's'}`; }

export function Progress({game: g}) {
  const {game} = g;
  const col = useCollection('rounds', {limit: 500});
  const rounds = col.records
    .map(r => ({id: r.id, ...r.data}))
    .filter(r => typeof r.turns === 'number')
    .sort((a, b) => (a.finishedAt || 0) - (b.finishedAt || 0));
  const count = rounds.length;
  const totalTurns = rounds.reduce((n, r) => n + r.turns, 0);
  const best = count ? Math.min(...rounds.map(r => r.turns)) : null;
  const avg = count ? (totalTurns / count).toFixed(1) : null;
